const MAX_INPUT:usize=256;
fn storeLe(out:[*]u8,off:usize,x:i64)void{const u:u64=@bitCast(x);for(0..8)|b|out[off+b]=@truncate(u>>(8*b));}
export fn unknown_sort(v:[*c]const i64,n:usize,out:[*c]u8,cap:usize)i64{if(v==null or n>257)return -1;if(n>MAX_INPUT)return -1;var work=[_]i64{0}**MAX_INPUT;var starts=[_]i64{0}**MAX_INPUT;var ends=[_]i64{0}**MAX_INPUT;var result=[_]i64{0}**MAX_INPUT;for(0..n)|i|work[i]=v[i];var count=n;var used:usize=0;var end_count:usize=0;while(count>1){var min_i:usize=0;var max_i:usize=0;for(1..count)|i|{if(work[i]<work[min_i])min_i=i;if(work[i]>work[max_i])max_i=i;}const min_v=work[min_i];const max_v=work[max_i];starts[used]=min_v;used+=1;ends[end_count]=max_v;end_count+=1;for(min_i..count-1)|i|work[i]=work[i+1];count-=1;var max_pos:usize=0;while(max_pos<count and work[max_pos]!=max_v):(max_pos+=1){}if(max_pos==count)return -1;for(max_pos..count-1)|i|work[i]=work[i+1];count-=1;}var out_n:usize=0;for(0..used)|i|{result[out_n]=starts[i];out_n+=1;}for(0..count)|i|{result[out_n]=work[i];out_n+=1;}var i=end_count;while(i>0){i-=1;result[out_n]=ends[i];out_n+=1;}const bytes=8*out_n;if(out==null or cap<bytes)return -2;for(0..out_n)|j|storeLe(out,8*j,result[j]);return @intCast(bytes);}
